query:
query($league:String!){
  fetchBaseMeasures(league:$league){
    categories
    description
    formatType
    onAirCatalogMeasureKey
    queryEngineMeasureKey
    sortDirectionDesc
    useLiveData
    format {
      __typename
      ... on DialectEngine_OnAirNumberMeasureFormat {
        decimalPlaceCount
        decimalShiftCount
        showPlusSymbol
        showZeroBeforeDecimal
        customSuffix
      }
      ... on DialectEngine_OnAirTimeMeasureFormat {
        timeFormatType
      }
    }
  }
}
